package com.jjm.oficina.servicio;
import org.junit.jupiter.api.Test;import java.time.*;
import static org.junit.jupiter.api.Assertions.*;
class AvisosMovilesTest {
 @Test void soloDiasHabilesALasSieteMexico(){assertTrue(AvisosMovilesService.esHorario(LocalDateTime.of(2026,10,27,7,0)));assertFalse(AvisosMovilesService.esHorario(LocalDateTime.of(2026,10,27,6,59)));assertFalse(AvisosMovilesService.esHorario(LocalDateTime.of(2026,10,27,8,0)));assertFalse(AvisosMovilesService.esHorario(LocalDateTime.of(2026,10,31,7,0)));}
 @Test void soloProveedoresPushHttps(){for(String s:new String[]{"https://fcm.googleapis.com/fcm/send/abc","https://web.push.apple.com/abc","https://updates.push.services.mozilla.com/wpush/v2/abc"})assertTrue(AvisosMovilesService.destinoPermitido(s));for(String s:new String[]{"http://fcm.googleapis.com/abc","https://127.0.0.1/","https://localhost/","https://fcm.googleapis.com.attacker.test/","https://user@fcm.googleapis.com/","https://fcm.googleapis.com:8080/","https://fcm.googleapis.com/#fragment"})assertFalse(AvisosMovilesService.destinoPermitido(s));}
 @Test void generaAvisoCifradoConFirmaVapid() throws Exception {
 java.security.Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());var g=java.security.KeyPairGenerator.getInstance("ECDH","BC");g.initialize(new java.security.spec.ECGenParameterSpec("prime256v1"));var servidor=g.generateKeyPair();var cliente=g.generateKeyPair();var b=java.util.Base64.getUrlEncoder().withoutPadding();String pub=b.encodeToString(nl.martijndwars.webpush.Utils.encode((org.bouncycastle.jce.interfaces.ECPublicKey)servidor.getPublic()));String priv=b.encodeToString(nl.martijndwars.webpush.Utils.encode((org.bouncycastle.jce.interfaces.ECPrivateKey)servidor.getPrivate()));String clave=b.encodeToString(nl.martijndwars.webpush.Utils.encode((org.bouncycastle.jce.interfaces.ECPublicKey)cliente.getPublic()));var push=new AvisosMovilesService.EmpaquePush(pub,priv,"https://oficina.jjmti.com.mx");var req=push.preparar(new nl.martijndwars.webpush.Notification("https://fcm.googleapis.com/fcm/send/prueba",clave,b.encodeToString(new byte[16]),"Aviso de prueba".getBytes(java.nio.charset.StandardCharsets.UTF_8),300),nl.martijndwars.webpush.Encoding.AES128GCM);assertTrue(req.getBody().length>20);assertTrue(req.getHeaders().keySet().stream().anyMatch(h->h.equalsIgnoreCase("Authorization")));var builder=java.net.http.HttpRequest.newBuilder(java.net.URI.create(req.getUrl()));req.getHeaders().forEach(builder::header);assertNotNull(builder.POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(req.getBody())).build());
 }
}
